"""Pure counting and formatting for wordstat (contract R3, R4, output formats)."""

import json
import re
from collections import Counter


def analyze(text: str, top_n: int) -> dict:
    tokens = re.findall(r"[a-z0-9]+", text.lower())
    counter = Counter(tokens)
    top = sorted(counter.items(), key=lambda kv: (-kv[1], kv[0]))[:top_n]
    return {
        "lines": len(text.splitlines()),
        "words": len(tokens),
        "chars": len(text),
        "top": [{"word": word, "count": count} for word, count in top],
    }


def render_text(result: dict) -> str:
    top = result["top"]
    if top:
        top_line = "top: " + " ".join(f"{item['word']}={item['count']}" for item in top)
    else:
        top_line = "top:"
    return (
        f"lines: {result['lines']}\n"
        f"words: {result['words']}\n"
        f"chars: {result['chars']}\n"
        f"{top_line}\n"
    )


def render_json(result: dict) -> str:
    obj = {
        "lines": result["lines"],
        "words": result["words"],
        "chars": result["chars"],
        "top": result["top"],
    }
    return json.dumps(obj) + "\n"

"""Command-line interface for wordstat (contract command, error table, R6 I/O)."""

import argparse
import sys

from . import counts


def _top_n(value: str) -> int:
    try:
        n = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid int value: '{value}'") from None
    if n < 1:
        raise argparse.ArgumentTypeError(f"invalid int value: '{value}'")
    return n


def _read_bytes(path: str) -> bytes:
    with open(path, "rb") as handle:
        return handle.read()


def _fail(body: str, code: int) -> int:
    print(f"wordstat: error: {body}", file=sys.stderr)
    return code


def main(argv: list[str] | None = None) -> int:
    sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    sys.stderr.reconfigure(encoding="utf-8", newline="\n")
    parser = argparse.ArgumentParser(prog="wordstat")
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--top", type=_top_n, default=3, metavar="N")
    parser.add_argument("path", metavar="FILE")
    args = parser.parse_args(argv)
    try:
        text = _read_bytes(args.path).decode("utf-8-sig", errors="strict")
        result = counts.analyze(text, args.top)
        output = counts.render_json(result) if args.json else counts.render_text(result)
    except UnicodeDecodeError:
        return _fail(f"{args.path}: not valid UTF-8", 3)
    except OSError:
        return _fail(f"{args.path}: cannot read file", 3)
    except Exception:
        return _fail("internal error", 1)
    sys.stdout.write(output)
    return 0

